/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getDomain = require( './domain/get.js' );
var setDomain = require( './domain/set.js' );
var getDomainMax = require( './domain-max/get.js' );
var setDomainMax = require( './domain-max/set.js' );
var getDomainMid = require( './domain-mid/get.js' );
var setDomainMid = require( './domain-mid/set.js' );
var getDomainMin = require( './domain-min/get.js' );
var setDomainMin = require( './domain-min/set.js' );
var getDomainRaw = require( './domain-raw/get.js' );
var setDomainRaw = require( './domain-raw/set.js' );

var getInterpolate = require( './interpolate/get.js' );
var setInterpolate = require( './interpolate/set.js' );

var getName = require( './name/get.js' );
var setName = require( './name/set.js' );

var getProperties = require( './properties/get.js' );

var getRange = require( './range/get.js' );
var setRange = require( './range/set.js' );
var getReverse = require( './reverse/get.js' );
var setReverse = require( './reverse/set.js' );
var getRound = require( './round/get.js' );
var setRound = require( './round/set.js' );

var getType = require( './type/get.js' );
var setType = require( './type/set.js' );


// VARIABLES //

var debug = logger( 'vega:scale:main' );


// MAIN //

/**
* Scale constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {string} options.name - scale name
* @param {(Collection|Object|Signal)} [options.domain] - domain of associated data values
* @param {number} [options.domainMax] - maximum value in the scale domain (overrides the `domain` option)
* @param {number} [options.domainMin] - minimum value in the scale domain (overrides the `domain` option)
* @param {number} [options.domainMid] - single mid-point value inserted into a two-element domain
* @param {Collection} [options.domainRaw] - array of raw domain values which overrides the `domain` property
* @param {(string|Object)} [options.interpolate] - scale range interpolation method
* @param {(Collection|Object|Signal|string)} [options.range] - scale range
* @param {boolean} [options.reverse=false] - boolean indicating whether to reverse the order of the scale range
* @param {boolean} [options.round=false] - boolean indicating whether to round numeric output values to integers
* @param {string} [options.type='linear'] - scale type
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {Scale} scale instance
*
* @example
* var scale = new Scale({
*     'name': 'xScale'
* });
* // returns <Scale>
*/
function Scale( options ) {
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof Scale ) ) {
		return new Scale( options );
	}
	EventEmitter.call( this );
	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}
	// Check for required properties...
	if ( !hasProp( options, 'name' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify the scale name.' );
	}
	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( Scale, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof Scale
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( Scale, 'name', 'Scale' );

/**
* Scale domain.
*
* @name domain
* @memberof Scale.prototype
* @type {(Array|Object|Signal|void)}
*
* @example
* var scale = new Scale({
*     'name': 'xScale',
*     'domain': [ 0, 100 ]
* });
*
* var v = scale.domain;
* // returns [ 0, 100 ]
*/
setReadWriteAccessor( Scale.prototype, 'domain', getDomain, setDomain );

/**
* Explicit scale domain maximum value.
*
* @name domainMax
* @memberof Scale.prototype
* @type {(number|void)}
*
* @example
* var scale = new Scale({
*     'name': 'xScale',
*     'domainMax': 100
* });
*
* var v = scale.domainMax;
* // returns 100
*/
setReadWriteAccessor( Scale.prototype, 'domainMax', getDomainMax, setDomainMax );

/**
* Mid-point inserted into a two-element scale domain.
*
* @name domainMid
* @memberof Scale.prototype
* @type {(number|void)}
*
* @example
* var scale = new Scale({
*     'name': 'xScale',
*     'domainMid': 50
* });
*
* var v = scale.domainMid;
* // returns 50
*/
setReadWriteAccessor( Scale.prototype, 'domainMid', getDomainMid, setDomainMid );

/**
* Explicit scale domain minimum value.
*
* @name domainMin
* @memberof Scale.prototype
* @type {(number|void)}
*
* @example
* var scale = new Scale({
*     'name': 'xScale',
*     'domainMin': 0
* });
*
* var v = scale.domainMin;
* // returns 0
*/
setReadWriteAccessor( Scale.prototype, 'domainMin', getDomainMin, setDomainMin );

/**
* Raw scale domain values.
*
* @name domainRaw
* @memberof Scale.prototype
* @type {(Array|void)}
*
* @example
* var scale = new Scale({
*     'name': 'xScale',
*     'domainRaw': [ 0, 1, 2, 3, 4, 5 ]
* });
*
* var v = scale.domainRaw;
* // returns [ 0, 1, 2, 3, 4, 5 ]
*/
setReadWriteAccessor( Scale.prototype, 'domainRaw', getDomainRaw, setDomainRaw );

/**
* Scale range interpolation method.
*
* @name interpolate
* @memberof Scale.prototype
* @type {(string|Object|void)}
*
* @example
* var scale = new Scale({
*     'name': 'xScale',
*     'interpolate': 'rgb'
* });
*
* var v = scale.interpolate;
* // returns 'rgb'
*/
setReadWriteAccessor( Scale.prototype, 'interpolate', getInterpolate, setInterpolate );

/**
* Scale name.
*
* @name name
* @memberof Scale.prototype
* @type {string}
*
* @example
* var scale = new Scale({
*     'name': 'xScale'
* });
*
* var v = scale.name;
* // returns 'xScale'
*/
setReadWriteAccessor( Scale.prototype, 'name', getName, setName );

/**
* Scale properties.
*
* @name properties
* @memberof Scale.prototype
* @type {Array<string>}
*
* @example
* var scale = new Scale({
*     'name': 'xScale'
* });
*
* var v = scale.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( Scale.prototype, 'properties', getProperties );

/**
* Scale range.
*
* @name range
* @memberof Scale.prototype
* @type {(Array|Object|Signal|string|void)}
*
* @example
* var scale = new Scale({
*     'name': 'xScale',
*     'range': [ 0, 100 ]
* });
*
* var v = scale.range;
* // returns [ 0, 100 ]
*/
setReadWriteAccessor( Scale.prototype, 'range', getRange, setRange );

/**
* Boolean indicating whether to reverse the order of the scale range.
*
* @name reverse
* @memberof Scale.prototype
* @type {boolean}
* @default false
*
* @example
* var scale = new Scale({
*     'name': 'xScale',
*     'reverse': true
* });
*
* var v = scale.reverse;
* // returns true
*/
setReadWriteAccessor( Scale.prototype, 'reverse', getReverse, setReverse );

/**
* Boolean indicating whether to round numeric output value to integers.
*
* @name round
* @memberof Scale.prototype
* @type {boolean}
* @default false
*
* @example
* var scale = new Scale({
*     'name': 'xScale',
*     'round': true
* });
*
* var v = scale.round;
* // returns true
*/
setReadWriteAccessor( Scale.prototype, 'round', getRound, setRound );

/**
* Scale type.
*
* @name type
* @memberof Scale.prototype
* @type {string}
* @default 'linear'
*
* @example
* var scale = new Scale({
*     'name': 'xScale',
*     'type': 'log'
* });
*
* var v = scale.type;
* // returns 'log'
*/
setReadWriteAccessor( Scale.prototype, 'type', getType, setType );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof Scale.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var scale = new Scale({
*     'name': 'xScale'
* });
*
* var v = scale.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( Scale.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = Scale;
